# Date: 2026-11-13
# Version: 2.0
#
# Description: This script uploads the prepared legacy monitoring payloads
# (generated by `06_prepare_kobo_upload.R`) to KoBoToolbox via the OpenRosa XML
# submission endpoint (`https://kc.kobotoolbox.org/api/v1/submissions`).
#
# Key features:
#   1. Resolves the target KoBo asset UID and deployed version ID dynamically
#      (defaults to `"Test 1"` for safe testing; switch `target_asset_name` to
#      `"NEW Tree Monitoring Form"` for production).
#   2. Generates a fresh UUID (`uuid::UUIDgenerate()`) for every uploaded
#      submission in `<meta><instanceID>uuid:...</instanceID></meta>`.
#   3. Serializes only the analysis-relevant fields and nested repeat groups
#      into an OpenRosa-compliant XML file and attaches any cached photos/files
#      via `multipart/form-data`.
#   4. Enforces rate limiting (`Sys.sleep()`) and writes both a human-readable
#      log file and a structured CSV mapping `legacy_uuid -> new_kobo_uuid`.
#
# Inputs:
#   - `.Renviron` storing `KOBO_API_TOKEN`
#   - `scripts/utils/config.R`
#   - `legacy_migration/legacy_upload/kobo_upload_payloads_latest.rds`
#
# Outputs:
#   - `legacy_migration/legacy_upload/upload_log_<timestamp>.txt`
#   - `legacy_migration/legacy_upload/upload_uuid_map_<timestamp>.csv`
# -#-#-#-#-#-#-#-#-#-#-#-#-#-#-#-#-#-#-#-#-#-#-#-#-#-#-#-#-#-#-#-#-#-#-#-#-#-#-

# -#-#-#-#-#-#-#-#-#-#-#-#-#-#-#-#-#-#-#-#-#-#-#-#-#-#-#-#-#-#-#-#-#-#-#-#-#-#-
#region 0. Load packages and configuration

source(here::here("scripts/utils/config.R"))
source(here::here("legacy_migration/legacy_scripts/00_legacy_migration_params.R"))

library(httr)
library(xml2)
library(jsonlite)
library(uuid)
library(robotoolbox)
library(dplyr)
library(readr)
library(here)

#endregion
# -#-#-#-#-#-#-#-#-#-#-#-#-#-#-#-#-#-#-#-#-#-#-#-#-#-#-#-#-#-#-#-#-#-#-#-#-#-#-
#region 1. Upload Configuration

# Target KoBo Asset Name:
#   - Use "Test 1" for testing and verification
#   - Switch to `kobo_asset_name` ("NEW Tree Monitoring Form") for production
target_asset_name <- "Test 1"
target_asset_uid  <- NULL # Optional explicit UID override; if NULL, looked up by name

# OpenRosa Submissions API endpoint (supports XML + media attachments)
KOBO_SUBMISSION_URL <- "https://kc.kobotoolbox.org/api/v1/submissions"

# Input payload bundle prepared by `06_prepare_kobo_upload.R`
upload_dir     <- file.path(dir_legacy, "legacy_upload")
payload_rds_in <- file.path(upload_dir, "kobo_upload_payloads_latest.rds")

# Toggle whether to attach binary photo/file media in the multipart POST
include_media <- TRUE

# Pause (in seconds) between consecutive POST requests to respect KoBo rate limits
sleep_seconds <- 1.5

# Optional cap on number of records to upload in this run (e.g., set to 5 for a
# quick smoke test, or NULL to upload all records in `payload_rds_in`)
max_records <- NULL

# Verify API token
KOBO_API_TOKEN <- Sys.getenv("KOBO_API_TOKEN")
if (!nzchar(KOBO_API_TOKEN)) {
  stop(
    "API token not found. Please set 'KOBO_API_TOKEN' in your .Renviron file.",
    call. = FALSE
  )
} else {
  cat("Configuration successful. KOBO_API_TOKEN loaded.\n")
}

# Resolve target KoBo Asset UID and deployed `__version__` dynamically
kobo_setup(url = "https://kf.kobotoolbox.org", token = KOBO_API_TOKEN)

target_asset <- if (!is.null(target_asset_uid) && nzchar(target_asset_uid)) {
  kobo_asset(target_asset_uid)
} else {
  asset_list <- kobo_asset_list()
  matched_uid <- asset_list %>%
    filter(name == target_asset_name) %>%
    pull(uid) %>%
    first()
  if (is.null(matched_uid) || is.na(matched_uid)) {
    stop(sprintf("Target asset '%s' not found in KoBo account.", target_asset_name), call. = FALSE)
  }
  kobo_asset(matched_uid)
}

FORM_ID      <- target_asset$uid
FORM_VERSION <- target_asset$deployed_version_id

cat(sprintf(
  "--> Target KoBo Asset : '%s'\n--> Asset UID (FORM_ID): %s\n--> Deployed Version  : %s\n",
  target_asset$name, FORM_ID, FORM_VERSION
))

#endregion
# -#-#-#-#-#-#-#-#-#-#-#-#-#-#-#-#-#-#-#-#-#-#-#-#-#-#-#-#-#-#-#-#-#-#-#-#-#-#-
#region 2. XML Payload Builder (`build_submission_xml`)

#' Recursively populate XML nodes from a nested R list
#'
#'Scalar values become `<tag>value</tag>`, data.frames (repeat groups) become
#'repeated `<tag>...</tag>` elements, and named lists become nested group nodes.
populate_xml_nodes <- function(parent_node, data_list) {
  for (field_name in names(data_list)) {
    val <- data_list[[field_name]]
    if (is.null(val)) next

    if (is.data.frame(val)) {
      # Repeat group: add one <field_name> node per row of the data.frame
      if (nrow(val) == 0) next
      for (r in seq_len(nrow(val))) {
        row_list <- as.list(val[r, , drop = FALSE])
        # Skip if all columns in this repeat row are NA
        non_na <- keep(row_list, ~ !is.null(.x) && !is.na(.x) && nzchar(trimws(as.character(.x))))
        if (length(non_na) == 0) next
        repeat_node <- xml_add_child(parent_node, field_name)
        for (col_nm in names(non_na)) {
          xml_add_child(repeat_node, col_nm, as.character(non_na[[col_nm]]))
        }
      }
    } else if (is.list(val)) {
      # Nested group: create group node and recurse
      if (length(val) == 0) next
      group_node <- xml_add_child(parent_node, field_name)
      populate_xml_nodes(group_node, val)
    } else if (length(val) == 1 && !is.na(val) && nzchar(trimws(as.character(val)))) {
      # Scalar field
      xml_add_child(parent_node, field_name, as.character(val))
    }
  }
}

#' Build an OpenRosa XML submission document for a single survey record
#'
#' @param form_data Named list of form fields/groups for one survey
#' @param form_id Target KoBo asset UID (`FORM_ID`)
#' @param form_version Target KoBo asset deployed version ID (`FORM_VERSION`)
#' @param instance_uuid Freshly generated UUID string (without `"uuid:"` prefix)
#' @return An `xml_document` ready to be written to a temporary `.xml` file
build_submission_xml <- function(form_data, form_id, form_version, instance_uuid) {
  root <- xml_new_root(form_id, id = form_id)

  # Populate all survey fields, groups, and repeat groups
  populate_xml_nodes(root, form_data)

  # Append form version and OpenRosa instanceID metadata
  if (!is.null(form_version) && !is.na(form_version) && nzchar(form_version)) {
    xml_add_child(root, "__version__", as.character(form_version))
  }
  meta_node <- xml_add_child(root, "meta")
  xml_add_child(meta_node, "instanceID", paste0("uuid:", instance_uuid))

  return(root)
}

#endregion
# -#-#-#-#-#-#-#-#-#-#-#-#-#-#-#-#-#-#-#-#-#-#-#-#-#-#-#-#-#-#-#-#-#-#-#-#-#-#-
#region 3. Upload Process

if (!file.exists(payload_rds_in)) {
  stop("Prepared payload file not found at: ", payload_rds_in, "\nRun 06_prepare_kobo_upload.R first.", call. = FALSE)
}

records <- readRDS(payload_rds_in)
if (!is.null(max_records) && is.numeric(max_records) && max_records > 0) {
  records <- head(records, max_records)
}

record_count <- length(records)
timestamp_str <- format(Sys.time(), "%Y%m%d_%H%M%S")
log_filepath  <- file.path(upload_dir, paste0("upload_log_", timestamp_str, ".txt"))
map_filepath  <- file.path(upload_dir, paste0("upload_uuid_map_", timestamp_str, ".csv"))

cat(
  paste0(
    "Upload started at: ", Sys.time(), "\n",
    "Target Asset     : ", target_asset$name, " (", FORM_ID, ")\n",
    "Total Records    : ", record_count, "\n",
    "Include Media    : ", include_media, "\n\n"
  ),
  file = log_filepath
)

cat(sprintf("\nStarting upload of %d record(s) to '%s' (%s)...\n", record_count, target_asset$name, FORM_ID))

uuid_map_rows <- vector("list", record_count)

for (i in seq_len(record_count)) {
  rec  <- records[[i]]
  meta <- rec$meta_info
  form_data <- rec$form_data

  # Generate a fresh KoBo UUID for this submission
  new_kobo_uuid <- uuid::UUIDgenerate()

  cat(sprintf(
    "\n[%d/%d] Uploading survey_key=%s | plot_id=%s (%s) | org=%s | timeframe=%s...\n",
    i, record_count, meta$survey_key, meta$plot_id, meta$plot_name, meta$org_id, meta$timeframe
  ))

  # If media attachments are disabled, strip media filenames from XML tags
  if (!include_media) {
    if (!is.null(form_data$gps_pictures_30x30)) {
      form_data$gps_pictures_30x30[c(
        "ne_photo_plot_30x30", "se_photo_plot_30x30",
        "sw_photo_plot_30x30", "nw_photo_plot_30x30"
      )] <- NULL
    }
    if (!is.null(form_data$gps_pictures_10x10)) {
      form_data$gps_pictures_10x10[c(
        "ne_photo_small_site", "se_photo_smallsites",
        "sw_photo_smallsites", "nw_photo_smallsites"
      )] <- NULL
    }
    if (!is.null(form_data$gps_pictures_3x3)) {
      form_data$gps_pictures_3x3[["photo_plot_3x3"]] <- NULL
    }
    form_data$files <- NULL
  }

  # Collect binary files to attach in multipart body
  files_to_attach <- list()
  if (include_media && length(rec$media_attachments) > 0) {
    for (field_nm in names(rec$media_attachments)) {
      f_path <- rec$media_attachments[[field_nm]]
      if (!is.null(f_path) && file.exists(f_path) && file.info(f_path)$size > 0) {
        files_to_attach[[field_nm]] <- httr::upload_file(f_path)
      } else {
        warning(sprintf("Media file missing on disk for plot_id %s (%s): %s", meta$plot_id, field_nm, f_path))
      }
    }
  }

  # Build XML document and write to temporary file
  xml_doc <- tryCatch(
    build_submission_xml(form_data, FORM_ID, FORM_VERSION, new_kobo_uuid),
    error = function(e) {
      warning(sprintf("XML generation error for survey_key %s: %s", meta$survey_key, e$message))
      NULL
    }
  )

  if (is.null(xml_doc)) {
    msg <- sprintf("SKIPPED record %d (survey_key=%s, plot_id=%s): XML creation failed.\n", i, meta$survey_key, meta$plot_id)
    cat(msg)
    cat(msg, file = log_filepath, append = TRUE)
    next
  }

  xml_temp_path <- tempfile(pattern = paste0("sub_", meta$survey_key, "_"), fileext = ".xml")
  xml2::write_xml(xml_doc, xml_temp_path)

  # Combine XML submission file and media files into multipart body
  body_list <- c(
    list(xml_submission_file = httr::upload_file(xml_temp_path, type = "text/xml")),
    files_to_attach
  )

  # Send POST request to KoBo OpenRosa endpoint
  response <- tryCatch(
    httr::POST(
      url    = KOBO_SUBMISSION_URL,
      body   = body_list,
      encode = "multipart",
      httr::add_headers(
        Authorization       = paste("Token", KOBO_API_TOKEN),
        `X-OpenRosa-Version` = "1.0"
      )
    ),
    error = function(e) {
      list(error_message = e$message)
    }
  )

  # Clean up temporary XML file
  if (file.exists(xml_temp_path)) file.remove(xml_temp_path)

  # Evaluate response status
  status_cd <- if (inherits(response, "response")) httr::status_code(response) else NA_integer_

  if (!is.na(status_cd) && status_cd %in% c(201L, 202L)) {
    msg <- sprintf(
      "SUCCESS [%d/%d]: survey_key=%s | plot_id=%s (%s) | media_files=%d | new_uuid=%s (HTTP %d)\n",
      i, record_count, meta$survey_key, meta$plot_id, meta$plot_name,
      length(files_to_attach), new_kobo_uuid, status_cd
    )
    cat(msg)
    cat(msg, file = log_filepath, append = TRUE)
  } else {
    resp_text <- if (inherits(response, "response")) {
      httr::content(response, "text", encoding = "UTF-8")
    } else {
      response$error_message
    }
    msg <- sprintf(
      "ERROR [%d/%d]: survey_key=%s | plot_id=%s (%s) | HTTP %s\n  Response: %s\n",
      i, record_count, meta$survey_key, meta$plot_id, meta$plot_name,
      as.character(status_cd), resp_text
    )
    cat(msg)
    cat(msg, file = log_filepath, append = TRUE)
  }

  uuid_map_rows[[i]] <- tibble(
    survey_key    = meta$survey_key,
    plot_id       = meta$plot_id,
    plot_name     = meta$plot_name,
    site_id       = meta$site_id,
    org_id        = meta$org_id,
    timeframe     = meta$timeframe,
    legacy_uuid   = meta$legacy_uuid,
    new_kobo_uuid = new_kobo_uuid,
    media_count   = length(files_to_attach),
    http_status   = status_cd,
    uploaded_at   = format(Sys.time(), "%Y-%m-%d %H:%M:%S")
  )

  # Pause to respect API rate limits
  if (i < record_count) Sys.sleep(sleep_seconds)
}

# Save UUID mapping & status table
uuid_map_df <- bind_rows(uuid_map_rows)
write_excel_csv(uuid_map_df, map_filepath)

cat(paste0("\nUpload finished at: ", Sys.time(), "\n"), file = log_filepath, append = TRUE)
cat("\n[OK] Upload process completed!\n")
cat("  • Detailed log   : ", log_filepath, "\n")
cat("  • UUID map & log : ", map_filepath, "\n")

#endregion
